const fs = require('fs');
const path = require('path');

const endpoint = 'http://127.0.0.1:64219/status';

async function main() {
  const res = await fetch(endpoint);
  const data = await res.json();

  const outDir = path.join(__dirname, 'results');
  fs.mkdirSync(outDir, { recursive: true });

  const outFile = path.join(outDir, 'status.json');
  fs.writeFileSync(outFile, JSON.stringify({ status: data.status }, null, 2) + '\n');

  console.log('wrote', outFile, data.status);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

